/* Microfix 3.8.37: language-aware Layers polish + reliable inline icons */
function bcProjectActionIcon(id){
  if(id==="renameProject")return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4l10.7-10.7a2.1 2.1 0 0 0-3-3L5 17v3Z"/><path d="m14.5 7.5 3 3"/></svg>';
  if(id==="newProject")return '<span class="project-action-plus">+</span>';
  if(id==="openProjectFile")return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7.5h6l2 2h10v9.5H3z"/><path d="M3 7.5V5h7l2 2"/></svg>';
  return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v11"/><path d="m8 10 4 4 4-4"/><path d="M5 20h14"/></svg>';
}
function bcSectionIcon(kind){
  if(kind==="files")return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7h7l2 2h9v10H3z"/></svg>';
  if(kind==="project")return '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8M8 13h6"/></svg>';
  return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 8 4-8 4-8-4 8-4Z"/><path d="m4 12 8 4 8-4M4 17l8 4 8-4"/></svg>';
}
function syncLayersPolishLanguage(){
  const previewText={en:"Layer thumbnails",ru:"Мини-превью слоёв",de:"Ebenen-Vorschauen",es:"Miniaturas de capas",ja:"レイヤーのサムネイル",zh:"图层缩略图"}[state.language]||"Layer thumbnails";
  const menuTitle={en:"Project menu",ru:"Меню проекта",de:"Projektmenü",es:"Menú del proyecto",ja:"プロジェクトメニュー",zh:"项目菜单"}[state.language]||"Project menu";
  const actions={renameProject:"renameWorld",newProject:"newWorld",openProjectFile:"openProjectFile",saveProjectFile:"backupProject"};
  Object.entries(actions).forEach(([id,key])=>{const btn=document.getElementById(id);if(!btn)return;btn.innerHTML=`<span class="project-action-icon">${bcProjectActionIcon(id)}</span><span class="project-action-label">${esc(tr(key))}</span>`});
  const preview=document.querySelector("#layerPreviewSetting > span");if(preview)preview.textContent=previewText;
  const toggle=document.getElementById("layersProjectMenuToggle");if(toggle)toggle.title=menuTitle;
  const tabs=[...document.querySelectorAll("#layersPanel .panel-tabs button")];
  if(tabs[0])tabs[0].innerHTML=`<span class="bc-section-icon">${bcSectionIcon("layers")}</span><span>${esc(tr("layers"))}</span>`;
  if(tabs[1])tabs[1].innerHTML=`<span class="bc-section-icon">${bcSectionIcon("files")}</span><span>${esc(tr("files"))}</span>`;
  const projectLabel=document.querySelector("#layersPanel .panel-head small[data-i18n=project]");if(projectLabel)projectLabel.innerHTML=`<span class="bc-section-icon bc-section-icon-small">${bcSectionIcon("project")}</span><span>${esc(tr("project"))}</span>`;
}
setTimeout(syncLayersPolishLanguage,0);

/* Microfix 3.8.37: thumbnails are cropped, never stretched; section/action icons are real inline SVG */
.layer-row .layer-thumb{flex:0 0 36px!important;width:36px!important;min-width:36px!important;max-width:36px!important;height:28px!important;min-height:28px!important;aspect-ratio:9/7!important;border-radius:6px!important;overflow:hidden!important;align-self:center!important;box-sizing:border-box!important}
.layer-row .layer-thumb img{width:100%!important;height:100%!important;object-fit:cover!important;object-position:center!important;display:block!important}
.layer-row:has(.layer-thumb)>svg{display:none!important}
.layer-row:has(.layer-thumb){min-height:42px!important}
.project-action-icon{flex:0 0 18px!important;width:18px!important;height:18px!important;display:grid!important;place-items:center!important;color:var(--muted)!important}
.project-action-icon svg,.bc-section-icon svg{width:15px!important;height:15px!important;fill:none!important;stroke:currentColor!important;stroke-width:1.8!important;stroke-linecap:round!important;stroke-linejoin:round!important;display:block!important}
.project-action-plus{font-size:20px!important;line-height:16px!important;font-weight:500!important;margin-top:-1px}
.project-action-label{flex:1!important;min-width:0!important}
#layersPanel .panel-tabs button{display:flex!important;align-items:center!important;justify-content:center!important;gap:7px!important}
.bc-section-icon{width:17px;height:17px;display:grid;place-items:center;flex:0 0 17px;color:currentColor}
#layersPanel .panel-head small[data-i18n=project]{display:flex!important;align-items:center!important;gap:5px!important}
.bc-section-icon-small{width:13px;height:13px;flex-basis:13px}
.bc-section-icon-small svg{width:12px!important;height:12px!important}
